const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;
const ChaosCoreKernel = @import("../core_relational/chaos_core.zig").ChaosCoreKernel;
const SSI = @import("../index/ssi.zig").SSI;
const MGT = @import("../tokenizer/mgt.zig").MGT;
const Tensor = @import("../core/tensor.zig").Tensor;
const GPUCoordinator = @import("../distributed/gpu_coordinator.zig").GPUCoordinator;

pub const ContextTier = enum(u8) {
    Hot = 0,
    Warm = 1,
    Cold = 2,
    Archive = 3,
};

pub const ContextDescriptor = packed struct {
    agent_id: u64,
    anchor_hash: u64,
    last_active_timestamp: u64,
    surprise_score: f32,
    tier: ContextTier,
    model_slot: usize,
    streaming_offset: usize,
    state_hash: [32]u8,
};

pub const ModelSlot = struct {
    slot_id: usize,
    active_agent_id: u64,
    context_tensor: Tensor,
    segment_hashes: std.ArrayList([32]u8),
    allocator: Allocator,

    pub fn init(allocator: Allocator, slot_id: usize, dim: usize) !ModelSlot {
        return ModelSlot{
            .slot_id = slot_id,
            .active_agent_id = 0,
            .context_tensor = try Tensor.init(allocator, &[_]usize{ 1000000, dim }),
            .segment_hashes = std.ArrayList([32]u8).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ModelSlot) void {
        self.context_tensor.deinit();
        self.segment_hashes.deinit();
    }
};

pub const ContextSupervisor = struct {
    agents: std.AutoHashMap(u64, ContextDescriptor),
    slots: std.ArrayList(ModelSlot),
    chaos_core: *ChaosCoreKernel,
    ssi: *SSI,
    tokenizer: *MGT,
    gpu_coord: *GPUCoordinator,
    allocator: Allocator,
    current_timestamp: u64,
    total_capacity: usize,

    pub fn init(allocator: Allocator, num_slots: usize, dim: usize, chaos_core: *ChaosCoreKernel, ssi: *SSI, tokenizer: *MGT, gpu_coord: *GPUCoordinator) !ContextSupervisor {
        var slots = std.ArrayList(ModelSlot).init(allocator);
        var i: usize = 0;
        while (i < num_slots) : (i += 1) {
            try slots.append(try ModelSlot.init(allocator, i, dim));
        }
        return ContextSupervisor{
            .agents = std.AutoHashMap(u64, ContextDescriptor).init(allocator),
            .slots = slots,
            .chaos_core = chaos_core,
            .ssi = ssi,
            .tokenizer = tokenizer,
            .gpu_coord = gpu_coord,
            .allocator = allocator,
            .current_timestamp = 0,
            .total_capacity = num_slots,
        };
    }

    pub fn deinit(self: *ContextSupervisor) void {
        self.agents.deinit();
        for (self.slots.items) |*slot| {
            slot.deinit();
        }
        self.slots.deinit();
    }

    pub fn registerAgent(self: *ContextSupervisor, agent_id: u64, initial_state: []const u8) !void {
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(initial_state, &hash, .{});
        const block_id = try self.chaos_core.allocateMemory(initial_state, null);
        const desc = ContextDescriptor{
            .agent_id = agent_id,
            .anchor_hash = 0,
            .last_active_timestamp = self.current_timestamp,
            .surprise_score = 100.0,
            .tier = .Cold,
            .model_slot = math.maxInt(usize),
            .streaming_offset = 0,
            .state_hash = block_id[0..32].*,
        };
        try self.agents.put(agent_id, desc);
    }

    pub fn unregisterAgent(self: *ContextSupervisor, agent_id: u64) bool {
        return self.agents.remove(agent_id);
    }

    pub fn promoteToHot(self: *ContextSupervisor, agent_id: u64) !usize {
        var agent_ptr = self.agents.getPtr(agent_id) orelse return error.AgentNotFound;
        if (agent_ptr.tier == .Hot) {
            agent_ptr.last_active_timestamp = self.current_timestamp;
            return agent_ptr.model_slot;
        }
        const slot_id = try self.evictLeastSurprising();
        var slot = &self.slots.items[slot_id];
        const state_data = self.chaos_core.readMemory(agent_ptr.state_hash) orelse return error.MemoryBlockMissing;
        try self.unpackAgentState(slot, state_data);
        slot.active_agent_id = agent_id;
        agent_ptr.tier = .Hot;
        agent_ptr.model_slot = slot_id;
        agent_ptr.last_active_timestamp = self.current_timestamp;
        try self.ssi.addSequence(agent_ptr.anchor_hash, @as(u64, @intCast(self.current_timestamp)), true);
        return slot_id;
    }

    pub fn demoteToWarm(self: *ContextSupervisor, agent_id: u64) !void {
        var agent_ptr = self.agents.getPtr(agent_id) orelse return error.AgentNotFound;
        if (agent_ptr.tier != .Hot) return;
        const slot = &self.slots.items[agent_ptr.model_slot];
        const packed_state = try self.packAgentState(slot);
        defer self.allocator.free(packed_state);
        const block_id = try self.chaos_core.allocateMemory(packed_state, null);
        mem.copyForwards(u8, &agent_ptr.state_hash, block_id[0..32]);
        agent_ptr.tier = .Warm;
        agent_ptr.model_slot = math.maxInt(usize);
        slot.active_agent_id = 0;
    }

    pub fn demoteToCold(self: *ContextSupervisor, agent_id: u64) !void {
        var agent_ptr = self.agents.getPtr(agent_id) orelse return error.AgentNotFound;
        if (agent_ptr.tier == .Hot) {
            try self.demoteToWarm(agent_id);
        }
        agent_ptr.tier = .Cold;
    }

    pub fn evictLeastSurprising(self: *ContextSupervisor) !usize {
        var min_surprise: f32 = math.inf(f32);
        var target_agent: u64 = 0;
        var target_slot: usize = 0;
        var found: bool = false;
        var iter = self.agents.iterator();
        while (iter.next()) |entry| {
            const desc = entry.value_ptr.*;
            if (desc.tier == .Hot) {
                if (desc.surprise_score < min_surprise) {
                    min_surprise = desc.surprise_score;
                    target_agent = desc.agent_id;
                    target_slot = desc.model_slot;
                    found = true;
                }
            }
        }
        if (found) {
            try self.demoteToWarm(target_agent);
            return target_slot;
        }
        var i: usize = 0;
        while (i < self.total_capacity) : (i += 1) {
            if (self.slots.items[i].active_agent_id == 0) return i;
        }
        return error.NoAvailableSlots;
    }

    pub fn executeInterAgentInteraction(self: *ContextSupervisor, agent_a: u64, agent_b: u64, interaction_data: []const u8) !void {
        self.current_timestamp += 1;
        var ptr_a = self.agents.getPtr(agent_a) orelse return error.AgentNotFound;
        var ptr_b = self.agents.getPtr(agent_b) orelse return error.AgentNotFound;
        ptr_a.surprise_score += 15.0;
        ptr_b.surprise_score += 15.0;
        const a_slot = if (ptr_a.tier == .Hot) ptr_a.model_slot else try self.promoteToHot(agent_a);
        const b_slot = if (ptr_b.tier == .Hot) ptr_b.model_slot else try self.promoteToHot(agent_b);
        try self.broadcastTemporalEdge(agent_a, agent_b, interaction_data);
        const interaction_tokens = try self.tokenizer.tokenize(interaction_data, self.allocator);
        defer self.allocator.free(interaction_tokens);
        try self.injectTokensToSlot(&self.slots.items[a_slot], interaction_tokens);
        try self.injectTokensToSlot(&self.slots.items[b_slot], interaction_tokens);
    }

    pub fn microForwardPass(self: *ContextSupervisor, agent_id: u64) !void {
        var agent_ptr = self.agents.getPtr(agent_id) orelse return error.AgentNotFound;
        if (agent_ptr.tier != .Warm) return;
        const state_data = self.chaos_core.readMemory(agent_ptr.state_hash) orelse return error.MemoryBlockMissing;
        var simulated_tensor = try Tensor.init(self.allocator, &[_]usize{ 1, 1024 });
        defer simulated_tensor.deinit();
        var i: usize = 0;
        const limit = @min(state_data.len / 4, 1024);
        while (i < limit) : (i += 1) {
            simulated_tensor.data[i] = @as(f32, @floatFromInt(state_data[i * 4])) * 0.001;
        }
        const delta = try self.computeSurpriseDelta(simulated_tensor);
        agent_ptr.surprise_score = math.clamp(agent_ptr.surprise_score + delta, 0.0, 100.0);
        agent_ptr.last_active_timestamp = self.current_timestamp;
    }

    fn computeSurpriseDelta(self: *ContextSupervisor, tensor: Tensor) !f32 {
        _ = self;
        var sum: f32 = 0.0;
        for (tensor.data) |v| {
            sum += v * v;
        }
        return @max(0.1, math.sqrt(sum) * 0.05);
    }

    fn packAgentState(self: *ContextSupervisor, slot: *ModelSlot) ![]u8 {
        const tensor_bytes = slot.context_tensor.data.len * @sizeOf(f32);
        const packed = try self.allocator.alloc(u8, tensor_bytes + 8);
        mem.writeInt(u64, packed[0..8], slot.active_agent_id, .Little);
        const tensor_slice = mem.sliceAsBytes(slot.context_tensor.data);
        mem.copyForwards(u8, packed[8..], tensor_slice);
        return packed;
    }

    fn unpackAgentState(self: *ContextSupervisor, slot: *ModelSlot, data: []const u8) !void {
        if (data.len < 8) return error.CorruptStateData;
        slot.active_agent_id = mem.readInt(u64, data[0..8][0..8], .Little);
        const tensor_slice = mem.bytesAsSlice(f32, @as([]u8, @constCast(data[8..])));
        const limit = @min(slot.context_tensor.data.len, tensor_slice.len);
        mem.copyForwards(f32, slot.context_tensor.data[0..limit], tensor_slice[0..limit]);
    }

    fn broadcastTemporalEdge(self: *ContextSupervisor, agent_a: u64, agent_b: u64, data: []const u8) !void {
        var payload = try self.allocator.alloc(u8, 16 + data.len);
        defer self.allocator.free(payload);
        mem.writeInt(u64, payload[0..8], agent_a, .Little);
        mem.writeInt(u64, payload[8..16], agent_b, .Little);
        mem.copyForwards(u8, payload[16..], data);
        try self.gpu_coord.broadcast(payload, 0);
    }

    fn injectTokensToSlot(self: *ContextSupervisor, slot: *ModelSlot, tokens: []const u32) !void {
        _ = self;
        var i: usize = 0;
        while (i < tokens.len and i < slot.context_tensor.data.len) : (i += 1) {
            slot.context_tensor.data[i] = @as(f32, @floatFromInt(tokens[i])) * 0.01;
        }
    }

    pub fn tick(self: *ContextSupervisor) !void {
        self.current_timestamp += 1;
        var iter = self.agents.iterator();
        while (iter.next()) |entry| {
            var desc = entry.value_ptr;
            if (desc.tier == .Hot) {
                desc.surprise_score = @max(0.0, desc.surprise_score - 0.05);
            } else if (desc.tier == .Warm) {
                if (self.current_timestamp - desc.last_active_timestamp > 100) {
                    try self.microForwardPass(desc.agent_id);
                }
                if (desc.surprise_score < 5.0) {
                    try self.demoteToCold(desc.agent_id);
                }
            }
        }
    }

    pub fn synchronizeAgents(self: *ContextSupervisor) !void {
        var sync_buffer = try self.allocator.alloc(u8, self.agents.count() * @sizeOf(ContextDescriptor));
        defer self.allocator.free(sync_buffer);
        var iter = self.agents.iterator();
        var offset: usize = 0;
        while (iter.next()) |entry| {
            const bytes = mem.asBytes(entry.value_ptr);
            mem.copyForwards(u8, sync_buffer[offset..], bytes);
            offset += bytes.len;
        }
        try self.gpu_coord.allReduce(sync_buffer, sync_buffer, sync_buffer.len, 0);
        var i: usize = 0;
        while (i < sync_buffer.len) : (i += @sizeOf(ContextDescriptor)) {
            const desc_ptr = mem.bytesAsValue(ContextDescriptor, sync_buffer[i .. i + @sizeOf(ContextDescriptor)]);
            if (self.agents.getPtr(desc_ptr.agent_id)) |local_ptr| {
                if (desc_ptr.last_active_timestamp > local_ptr.last_active_timestamp) {
                    local_ptr.surprise_score = desc_ptr.surprise_score;
                    local_ptr.last_active_timestamp = desc_ptr.last_active_timestamp;
                    mem.copyForwards(u8, &local_ptr.state_hash, &desc_ptr.state_hash);
                }
            } else {
                try self.agents.put(desc_ptr.agent_id, desc_ptr.*);
            }
        }
    }

    pub fn forceArchive(self: *ContextSupervisor) !void {
        var iter = self.agents.iterator();
        while (iter.next()) |entry| {
            try self.demoteToCold(entry.key_ptr.*);
            entry.value_ptr.tier = .Archive;
        }
    }
};
